import csv
import math
from pathlib import Path

import matplotlib.pyplot as plt


# ============================================================
# Phase 6.3
# ROS2 Pose Estimation Validation Visualization
#
# Input:
#   500 synchronized GT / RAW / EST samples generated by ROS2
#
# Outputs:
#   1. Pose tracking comparison
#   2. 3D position-error comparison
#   3. Cumulative RMSE convergence
# ============================================================


PROJECT_ROOT = Path(__file__).resolve().parents[1]

CSV_FILE = (
    PROJECT_ROOT
    / "results"
    / "phase6_estimation"
    / "phase6_pose_estimation_samples.csv"
)

OUTPUT_DIR = (
    PROJECT_ROOT
    / "results"
    / "phase6_estimation"
    / "plots"
)

OUTPUT_DIR.mkdir(
    parents=True,
    exist_ok=True
)


# ============================================================
# Load ROS2-generated validation dataset
# ============================================================

sample_index = []

gt_x = []
gt_y = []
gt_z = []

raw_x = []
raw_y = []
raw_z = []

est_x = []
est_y = []
est_z = []

raw_error_3d_mm = []
est_error_3d_mm = []


with CSV_FILE.open("r", newline="") as csv_file:
    reader = csv.DictReader(csv_file)

    for row in reader:

        sample_index.append(
            int(row["sample_index"])
        )

        gt_x.append(float(row["gt_x_m"]))
        gt_y.append(float(row["gt_y_m"]))
        gt_z.append(float(row["gt_z_m"]))

        raw_x.append(float(row["raw_x_m"]))
        raw_y.append(float(row["raw_y_m"]))
        raw_z.append(float(row["raw_z_m"]))

        est_x.append(float(row["est_x_m"]))
        est_y.append(float(row["est_y_m"]))
        est_z.append(float(row["est_z_m"]))

        raw_error_3d_mm.append(
            float(row["raw_position_error_m"]) * 1000.0
        )

        est_error_3d_mm.append(
            float(row["est_position_error_m"]) * 1000.0
        )


if not sample_index:
    raise RuntimeError(
        "No validation samples found in CSV."
    )


# ============================================================
# Calculate final RMSE directly from dataset
# ============================================================

raw_squared_error_sum = 0.0
est_squared_error_sum = 0.0

cumulative_raw_rmse_mm = []
cumulative_est_rmse_mm = []


for i in range(len(sample_index)):

    raw_dx = raw_x[i] - gt_x[i]
    raw_dy = raw_y[i] - gt_y[i]
    raw_dz = raw_z[i] - gt_z[i]

    est_dx = est_x[i] - gt_x[i]
    est_dy = est_y[i] - gt_y[i]
    est_dz = est_z[i] - gt_z[i]


    raw_squared_error = (
        raw_dx * raw_dx
        + raw_dy * raw_dy
        + raw_dz * raw_dz
    )

    est_squared_error = (
        est_dx * est_dx
        + est_dy * est_dy
        + est_dz * est_dz
    )


    raw_squared_error_sum += raw_squared_error
    est_squared_error_sum += est_squared_error


    number_of_samples = i + 1


    cumulative_raw_rmse_mm.append(
        math.sqrt(
            raw_squared_error_sum
            / number_of_samples
        )
        * 1000.0
    )

    cumulative_est_rmse_mm.append(
        math.sqrt(
            est_squared_error_sum
            / number_of_samples
        )
        * 1000.0
    )


final_raw_rmse_mm = (
    cumulative_raw_rmse_mm[-1]
)

final_est_rmse_mm = (
    cumulative_est_rmse_mm[-1]
)

rmse_reduction_percent = (
    100.0
    * (
        final_raw_rmse_mm
        - final_est_rmse_mm
    )
    / final_raw_rmse_mm
)


# ============================================================
# Plot 1
# Ground Truth vs Raw vs Kalman Estimate
# ============================================================

plt.figure(
    figsize=(12, 6)
)

plt.plot(
    sample_index,
    gt_x,
    label="Ground Truth X",
    linewidth=2.0
)

plt.plot(
    sample_index,
    raw_x,
    label="Raw Measurement X",
    linewidth=0.8
)

plt.plot(
    sample_index,
    est_x,
    label="Kalman Estimate X",
    linewidth=1.5
)

plt.xlabel(
    "Evaluation Sample"
)

plt.ylabel(
    "X Position (m)"
)

plt.title(
    "Phase 6.3 — Pose Tracking: "
    "Ground Truth vs Raw Measurement vs Kalman Estimate"
)

plt.grid(
    True,
    alpha=0.3
)

plt.legend()

plt.tight_layout()

plt.savefig(
    OUTPUT_DIR
    / "phase6_pose_tracking_x.png",
    dpi=200
)

plt.close()


# ============================================================
# Plot 2
# Raw vs Estimated 3D Position Error
# ============================================================

plt.figure(
    figsize=(12, 6)
)

plt.plot(
    sample_index,
    raw_error_3d_mm,
    label="Raw Measurement Error",
    linewidth=1.0
)

plt.plot(
    sample_index,
    est_error_3d_mm,
    label="Kalman Estimate Error",
    linewidth=1.5
)

plt.xlabel(
    "Evaluation Sample"
)

plt.ylabel(
    "3D Position Error (mm)"
)

plt.title(
    "Phase 6.3 — 3D Position Error: "
    "Raw Measurement vs Kalman Estimate"
)

plt.grid(
    True,
    alpha=0.3
)

plt.legend()

plt.tight_layout()

plt.savefig(
    OUTPUT_DIR
    / "phase6_position_error_timeseries.png",
    dpi=200
)

plt.close()


# ============================================================
# Plot 3
# Cumulative 3D RMSE Convergence
# ============================================================

plt.figure(
    figsize=(12, 6)
)

plt.plot(
    sample_index,
    cumulative_raw_rmse_mm,
    label="Raw Measurement RMSE",
    linewidth=1.5
)

plt.plot(
    sample_index,
    cumulative_est_rmse_mm,
    label="Kalman Estimate RMSE",
    linewidth=1.5
)

plt.axhline(
    final_raw_rmse_mm,
    linestyle="--",
    linewidth=1.0,
    label=(
        f"Final Raw RMSE = "
        f"{final_raw_rmse_mm:.3f} mm"
    )
)

plt.axhline(
    final_est_rmse_mm,
    linestyle="--",
    linewidth=1.0,
    label=(
        f"Final Estimate RMSE = "
        f"{final_est_rmse_mm:.3f} mm"
    )
)

plt.xlabel(
    "Number of Evaluation Samples"
)

plt.ylabel(
    "Cumulative 3D RMSE (mm)"
)

plt.title(
    "Phase 6.3 — Cumulative 3D RMSE Convergence"
)

plt.grid(
    True,
    alpha=0.3
)

plt.legend()

plt.tight_layout()

plt.savefig(
    OUTPUT_DIR
    / "phase6_rmse_convergence.png",
    dpi=200
)

plt.close()


# ============================================================
# Engineering summary
# ============================================================

print("")
print(
    "============================================================"
)

print(
    " PHASE 6.3 VISUALIZATION AND METRIC VERIFICATION"
)

print(
    "============================================================"
)

print(
    f"Evaluation samples       : "
    f"{len(sample_index)}"
)

print(
    f"Final RAW 3D RMSE        : "
    f"{final_raw_rmse_mm:.3f} mm"
)

print(
    f"Final EST 3D RMSE        : "
    f"{final_est_rmse_mm:.3f} mm"
)

print(
    f"3D RMSE reduction        : "
    f"{rmse_reduction_percent:.2f} %"
)

print(
    "------------------------------------------------------------"
)

print(
    "Generated plots:"
)

print(
    "1. phase6_pose_tracking_x.png"
)

print(
    "2. phase6_position_error_timeseries.png"
)

print(
    "3. phase6_rmse_convergence.png"
)

print(
    "------------------------------------------------------------"
)

print(
    "Input CSV:"
)

print(
    CSV_FILE
)

print(
    "Output directory:"
)

print(
    OUTPUT_DIR
)

print(
    "============================================================"
)
